    function SafeGetValue(obj, path, defaultValue = "N/A") { let keys = Array.isArray(path) ? path : path.split('.'); let current = obj; for (let i = 0; i < keys.length; i++) { if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) { return defaultValue; } current = current[keys[i]]; } if (current === undefined || current === null) { return defaultValue; } if (Array.isArray(current)) { return current.length > 0 ? String(current[0]) : defaultValue; } return String(current); }
    function updateProgressBar(barId, valueMainId, valueDescId, rawValue, min, max) { const bar = document.getElementById(barId); const main = document.getElementById(valueMainId); const desc = document.getElementById(valueDescId); if (!main) return; main.innerText = SafeGetValue({ temp: rawValue }, 'temp', String(min)); if (desc) { desc.innerText = `(${SafeGetValue(rawValue, '1', '')})` } if (bar) { let numericValue = parseFloat(SafeGetValue(rawValue, '0', String(min))); numericValue = Math.max(min, Math.min(max, numericValue)); const percentage = max === min ? 100 : ((numericValue - min) / (max - min)) * 100; bar.style.width = `${percentage}%`; } }
    function toggleSection(element) { const content = element.nextElementSibling; const arrow = element.querySelector('span:last-child'); if (!content || !arrow) return; const isExpanded = content.classList.toggle('expanded'); element.classList.toggle('expanded-header', isExpanded); arrow.innerText = isExpanded ? '▲' : '▼'; }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            const characterData = messages?.[0]?.data?.stat_data;
            if (!characterData) { return; }

            // 更新梦淮南的状态
            updateProgressBar('huainan-affection-bar', 'huainan-affection', null, SafeGetValue(characterData, '梦淮南.好感度'), 0, 200);
            document.getElementById('huainan-stage').innerText = `(${SafeGetValue(characterData, '梦淮南.当前情感阶段.0', '...')})`;

            // 更新师尊纳威的状态
            updateProgressBar('nawei-affection-bar', 'nawei-affection', null, SafeGetValue(characterData, '纳威.好感度'), 0, 100);
            document.getElementById('nawei-stage').innerText = `(${SafeGetValue(characterData, '纳威.当前戏剧阶段.0', '...')})`;

            // 更新世界状态
            document.getElementById('world-time').innerText = SafeGetValue(characterData, '世界.当前时间.0', '--:--');
            document.getElementById('world-location').innerText = SafeGetValue(characterData, '世界.当前位置.0', '未知');
            document.getElementById('world-turn').innerText = SafeGetValue(characterData, '世界.对话轮次.0', '0');

        } catch (error) {
            console.error("状态栏加载出错:", error);
        }
    }
    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
</body>
</html>

